insert into org.parametro (tipo, nome, onde, quem_propoe, quem_decide, valor) select tipo, nome, onde, quem_propoe, quem_decide, valor from jsonb_to_recordset($j$[{"tipo": "alçada", "nome": "Concessão comercial de quem vende: faixa de desconto e condições de pagamento", "onde": "NE-01, NE-03, NE-04, NE-05, NE-06", "quem_propoe": "Negócios", "quem_decide": "Governança aprova a faixa; acima de quem vende, o executivo; acima do executivo, os sócios", "valor": "Faixa da oferta = preço de tabela até o preço-base (NE-01). Quem vende: até metade da faixa. Executivo: até o preço-base e condição de pagamento fora da política. Sócios: abaixo do preço-base, exclusividade, prazo maior que o ciclo. Contrato público: o que o edital permite (aprovado em 03/10/2026, 13:51)"}, {"tipo": "alçada", "nome": "Recursos de aposta e limite de recursos de cada unidade do portfólio", "onde": "ES-02, ES-04", "quem_propoe": "Estratégia", "quem_decide": "Estratégia, dentro da alocação; acima, os sócios", "valor": "Sócios fixam a reserva de apostas e o limite de cada unidade (ES-02). Estratégia: cada aposta dentro da reserva, até um terço dela. Acima: sócios (aprovado em 03/10/2026, 13:51)"}, {"tipo": "alçada", "nome": "Limite do ajuste de oferta em uso (o que dispensa o portão)", "onde": "IN-07", "quem_propoe": "Inteligência", "quem_decide": "Estratégia (decidido por você em 03/10/2026)", "valor": "Dispensa o portão se: não muda o público, não muda a promessa nem o escopo principal, não reduz o preço-base, não pede capacidade nova e não muda o risco do contrato-modelo (aprovado em 03/10/2026, 13:51)"}, {"tipo": "alçada", "nome": "Parceria e relação institucional", "onde": "RE-06", "quem_propoe": "Relações", "quem_decide": "Relações, dentro da alçada; acima, os sócios", "valor": "Relações: sem exclusividade, remuneração na regra dos sócios, marca pelo pacote, prazo até o fim do ciclo, sem obrigação além do orçamento do círculo. Fora disso: sócios (aprovado em 03/10/2026, 13:51)"}, {"tipo": "alçada", "nome": "Critérios de decisão e limites dos agentes", "onde": "ID-02, IT-05, IT-06, GO-06", "quem_propoe": "Identidade e Integração", "quem_decide": "Sócios aprovam (ID-02, etapa 3), dono único; a Governança confere", "valor": "Agente sem tarefa de julgamento; sem pessoa no caminho só em risco baixo ou médio, com auditoria por amostra no médio; liberação com teste e alçada conferida; suspensão por desvio, confirmada por pessoa (aprovado em 03/10/2026, 13:51; ajustado às 16:05)"}, {"tipo": "alçada", "nome": "Cobertura de falta de capacidade", "onde": "OP-01", "quem_propoe": "Operações", "quem_decide": "Operações; acima, o executivo", "valor": "Operações: pessoas e parceiros já contratados, dentro do orçamento. Contratação nova ou fora do orçamento: executivo, pela GE-01 (aprovado em 03/10/2026, 13:51)"}, {"tipo": "alçada", "nome": "Solução e compensação de reclamação", "onde": "OP-04", "quem_propoe": "Operações", "quem_decide": "Operações; acima, o executivo, com a Governança", "valor": "Operações: refazer e crédito até o valor faturado da entrega reclamada. Acima, ou responsabilidade e indenização: executivo, com a avaliação da Governança no fluxo (aprovado em 03/10/2026, 13:51; ajustado às 16:05)"}, {"tipo": "alçada", "nome": "Pedido de recurso e remanejamento no orçamento", "onde": "GE-01", "quem_propoe": "Gestão", "quem_decide": "Gestão; acima, o executivo ou o Administrador do IMTS.OS; entre empresas, a Estratégia", "valor": "Gestão: dentro do mesmo círculo e empresa, sem mudar o total. Entre círculos da empresa: executivo. Círculos compartilhados do IMTS.OS: o Administrador do IMTS.OS. Entre empresas: Estratégia. Aumento do total: sócios (aprovado em 03/10/2026, 13:51; ajustado às 16:05)"}, {"tipo": "alçada", "nome": "Ação decidida no ritual de acompanhamento", "onde": "GE-02", "quem_propoe": "Líder do círculo", "quem_decide": "Líder do círculo; acima, o executivo", "valor": "Líder: dentro do orçamento e da alçada do círculo. Acima: executivo. Muda alvo: a Estratégia decide na ES-06. Pede recurso: GE-01. Desvio grave: ES-06 (aprovado em 03/10/2026, 13:51; ajustado às 16:05)"}, {"tipo": "alçada", "nome": "Limite de atraso da política de cobrança", "onde": "GE-03", "quem_propoe": "Gestão", "quem_decide": "Gestão", "valor": "Privado: cobrança no vencimento e no ciclo seguinte; na segunda fatura vencida, proposta de suspensão ao executivo. Público: lei e contrato (aprovado em 03/10/2026, 13:51)"}, {"tipo": "alçada", "nome": "Compra fora do orçamento e aprovação de pagamento", "onde": "GE-04", "quem_propoe": "Gestão", "quem_decide": "Gestão; aprova o líder do círculo; acima, o executivo", "valor": "Pagamento só com pedido, recebimento e nota conferidos; quem lança não aprova: aprova o líder do círculo, inclusive o reembolso. Fora do orçamento: executivo. Acima da reserva de contingência: sócios (aprovado em 03/10/2026, 13:51; ajustado às 16:05)"}, {"tipo": "alçada", "nome": "Execução de aportes, distribuição e mudanças de contas", "onde": "GE-05", "quem_propoe": "Gestão", "quem_decide": "Gestão; aprova o líder do círculo; acima, o executivo", "valor": "Gestão executa só o que os sócios decidiram. Contas e poderes bancários: executivo com a Governança; contas do IMTS.OS: Administrador do IMTS.OS com a Governança. Todo pagamento com duas pessoas (aprovado em 03/10/2026, 13:51; ajustado às 16:05)"}, {"tipo": "alçada", "nome": "Vaga, movimentação e desligamento", "onde": "GE-07", "quem_propoe": "Gestão", "quem_decide": "Gestão; acima, o executivo ou o Administrador do IMTS.OS; desligamento, o executivo com o líder", "valor": "Vaga no orçamento: Gestão com o líder. Fora do orçamento: executivo. Desligamento: executivo com o líder. Executivo ou líder de círculo: sócios. Pessoas dos círculos do IMTS.OS: Administrador do IMTS.OS. Folha e remuneração: aprova o executivo, na empresa, ou o Administrador, nos círculos (aprovado em 03/10/2026, 13:51; ajustado às 16:05)"}, {"tipo": "alçada", "nome": "Regra que a Governança decide sozinha", "onde": "GO-01", "quem_propoe": "Governança", "quem_decide": "Sócios definem o que fica na alçada da Governança", "valor": "Regras que aplicam regra geral aprovada; modelos de proposta e contrato; sigilo, dados e guarda; alçada de pessoas no círculo e de agentes no critério; matriz de riscos no apetite; rateio com a Estratégia; amostra. Aos sócios: alçadas dos executivos, regras gerais, exceções, a alçada da Governança e das pessoas da Governança, e os limites dos agentes. Quem decide sai da lista, por regra (aprovado em 03/10/2026, 13:51; ajustado às 16:05)"}, {"tipo": "cadência", "nome": "ID-05 · Avaliar se os padrões de identidade funcionam e decidir o que rever", "onde": "Cada ciclo de avaliação", "quem_propoe": null, "quem_decide": "Líder do círculo Identidade", "valor": "Semestral (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "ES-01 · Formular e revisar a estratégia do Ecossistema e de cada empresa", "onde": "Cada ciclo estratégico", "quem_propoe": null, "quem_decide": "Estratégia, no calendário do método de estratégia (sócios aprovam, ES-01)", "valor": "Anual, com revisão no meio do ciclo (método aprovado em 03/10/2026)"}, {"tipo": "cadência", "nome": "ES-02 · Rever o portfólio e realocar recursos entre empresas, ofertas e apostas", "onde": "Cada fechamento de período", "quem_propoe": null, "quem_decide": "Estratégia, no calendário do método de estratégia (sócios aprovam, ES-01)", "valor": "Semestral (método aprovado em 03/10/2026)"}, {"tipo": "cadência", "nome": "ES-03 · Desdobrar a estratégia em alvos e iniciativas de cada empresa e de cada círculo", "onde": "Cada ciclo de alvos", "quem_propoe": null, "quem_decide": "Estratégia, no calendário do método de estratégia (sócios aprovam, ES-01)", "valor": "Anual, com o ciclo (método aprovado em 03/10/2026)"}, {"tipo": "cadência", "nome": "ES-06 · Acompanhar a execução da estratégia e corrigir o rumo", "onde": "Cada revisão da estratégia", "quem_propoe": null, "quem_decide": "Estratégia, no calendário do método de estratégia (sócios aprovam, ES-01)", "valor": "Trimestral (método aprovado em 03/10/2026)"}, {"tipo": "cadência", "nome": "IN-01 · Ler o mercado, os clientes e os concorrentes e avisar das mudanças relevantes", "onde": "Cada ciclo de leitura", "quem_propoe": null, "quem_decide": "Líder do círculo Inteligência", "valor": "Mensal (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "IN-04 · Definir e medir os indicadores e publicar as análises", "onde": "Cada período de medição", "quem_propoe": null, "quem_decide": "Líder do círculo Inteligência", "valor": "Medição mensal; revisão dos indicadores anual, junto com os alvos (ES-03) (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "IN-05 · Curar as bases de conhecimento que pessoas e agentes consultam", "onde": "Cada revisão da base", "quem_propoe": null, "quem_decide": "Líder do círculo Inteligência", "valor": "Trimestral (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "IN-08 · Aprender com as lições e os resultados e recomendar melhorias", "onde": "Cada ciclo de aprendizado", "quem_propoe": null, "quem_decide": "Líder do círculo Inteligência", "valor": "Trimestral, antes da revisão da execução (ES-06) (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "RE-01 · Planejar a geração de demanda do ciclo por público, oferta e canal", "onde": "Cada ciclo de demanda", "quem_propoe": null, "quem_decide": "Líder do círculo Relações", "valor": "Trimestral (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "RE-03 · Qualificar os contatos e entregar a Negócios as oportunidades qualificadas", "onde": "Cada ciclo de nutrição e revisão da base", "quem_propoe": null, "quem_decide": "Líder do círculo Relações", "valor": "Nutrição contínua, por evento; revisão da base semestral (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "RE-04 · Desenhar a experiência do cliente: personas, mapa da jornada e padrões de experiência", "onde": "Cada revisão da experiência", "quem_propoe": null, "quem_decide": "Líder do círculo Relações", "valor": "Anual (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "RE-05 · Acompanhar o sucesso de cada cliente, da entrada à renovação, à expansão ou à perda", "onde": "Cada ciclo de acompanhamento do cliente", "quem_propoe": null, "quem_decide": "Líder do círculo Relações", "valor": "Trimestral, por cliente (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "RE-06 · Formar e cuidar de parcerias e relações institucionais e autorizar o uso da marca por terceiros", "onde": "Na revisão de cada parceria", "quem_propoe": null, "quem_decide": "Líder do círculo Relações", "valor": "Semestral, por parceria (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "RE-07 · Comunicar para fora: pauta, conteúdo, imprensa e porta-vozes", "onde": "Cada ciclo de pauta", "quem_propoe": null, "quem_decide": "Líder do círculo Relações", "valor": "Pauta mensal (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "RE-08 · Monitorar a percepção dos públicos e a reputação e acionar a resposta a crises", "onde": "Cada ciclo de monitoramento", "quem_propoe": null, "quem_decide": "Líder do círculo Relações", "valor": "Coleta contínua; análise mensal (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "NE-01 · Manter a tabela de preços, a política comercial e o material de venda de cada empresa", "onde": "Na revisão da tabela", "quem_propoe": null, "quem_decide": "Líder do círculo Negócios", "valor": "Semestral, e sempre que um preço-base mudar (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "NE-02 · Planejar as vendas do ciclo e prever a receita", "onde": "Cada ciclo de vendas e a cada período de previsão", "quem_propoe": null, "quem_decide": "Líder do círculo Negócios", "valor": "Ciclo de vendas trimestral; previsão mensal (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "NE-07 · Vender com parceiros e em oferta conjunta entre as empresas", "onde": "Na revisão da venda com parceiros", "quem_propoe": null, "quem_decide": "Líder do círculo Negócios", "valor": "Semestral (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "IT-01 · Gerir a carteira de projetos do Ecossistema e das empresas", "onde": "Cada ciclo de acompanhamento", "quem_propoe": null, "quem_decide": "Líder do círculo Integração", "valor": "Mensal (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "IT-05 · Atender pedidos de capacidade e de serviço e manter o catálogo de capacidades", "onde": "Na revisão do catálogo", "quem_propoe": null, "quem_decide": "Líder do círculo Integração", "valor": "Trimestral (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "IT-06 · Cuidar dos agentes e automações: montar, testar, liberar, monitorar e corrigir", "onde": "Cada ciclo de monitoramento", "quem_propoe": null, "quem_decide": "Líder do círculo Integração", "valor": "Mensal (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "IT-08 · Medir e redesenhar as jornadas ponta a ponta e manter o catálogo de jornadas", "onde": "Cada ciclo de melhoria", "quem_propoe": null, "quem_decide": "Líder do círculo Integração", "valor": "Trimestral (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "OP-01 · Planejar a capacidade de entrega de cada oferta e cobrir as faltas", "onde": "Cada ciclo de planejamento", "quem_propoe": null, "quem_decide": "Líder do círculo Operações", "valor": "Trimestral (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "OP-05 · Garantir a qualidade e os níveis de serviço: padrões, medida e ação corretiva", "onde": "Cada ciclo de avaliação da qualidade", "quem_propoe": null, "quem_decide": "Líder do círculo Operações", "valor": "Mensal (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "OP-06 · Abastecer e entregar o produto físico: demanda, materiais, produção, estoque e transporte", "onde": "Cada ciclo de planejamento de suprimentos", "quem_propoe": null, "quem_decide": "Líder do círculo Operações", "valor": "Mensal (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "GE-02 · Rodar o ritual de acompanhamento dos alvos e cobrar as ações", "onde": "Ritual de acompanhamento, no calendário do método de estratégia", "quem_propoe": null, "quem_decide": "Estratégia, no método de estratégia (sócios aprovam, ES-01)", "valor": "Mensal (método aprovado em 03/10/2026)"}, {"tipo": "cadência", "nome": "GE-05 · Gerir o caixa, fechar as contas e os impostos e prestar contas", "onde": "Cada período de fechamento", "quem_propoe": null, "quem_decide": "Líder do círculo Gestão", "valor": "Fechamento mensal; balanço anual (Código Civil, art. 1.179) (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "GE-06 · Aplicar o rateio do custo dos círculos entre as empresas", "onde": "Cada período de fechamento", "quem_propoe": null, "quem_decide": "Líder do círculo Gestão", "valor": "Mensal, com o fechamento (validado em 03/10/2026, 14:07; o líder ajusta na implantação)"}, {"tipo": "cadência", "nome": "GE-09 · Avaliar e desenvolver as pessoas e medir a cultura", "onde": "Cada ciclo de avaliação e desenvolvimento e a cada pesquisa de cultura", "quem_propoe": null, "quem_decide": "Líder do c